FILE: sys/arch/rp2040/dev/flash_swap.c

1	/*
2	 * Program one ascending piece of an erase-aligned raw swap image.
3	 *
4	 * The first nonempty piece starts at an erase-sector boundary. Later pieces
5	 * start at program-page boundaries in the same image and arrive in ascending
6	 * address order. A sector is therefore erased exactly when a piece first
7	 * reaches its boundary. A short final program page is padded with erased
8	 * bytes; the next piece starts beyond that page.
9	 *
10	 * Keeping the geometry loop separate from the flash driver lets the host test
11	 * run the production algorithm against a NOR model that rejects 0-to-1 bit
12	 * transitions, unaligned calls, duplicate erases, and overlapping images.
13	 */
14	
15	#include <sys/types.h>
16	
17	#include <rp2040/dev/flash.h>
18	#include <rp2040/dev/flash_swap.h>
19	
20	int
21	flash_swap_append(const struct flash_swap_ops *ops, unsigned int offset,
22	    const unsigned char *source, unsigned int length, unsigned char *scratch)
23	{
24		unsigned int chunk, index;
25	
26		if ((offset & (FLASH_PROG_BYTES - 1)) != 0)
27			return -1;
28	
29		while (length != 0) {
30			if ((offset & (FLASH_SECTOR_BYTES - 1)) == 0 &&
31			    ops->erase(offset, FLASH_SECTOR_BYTES) != 0)
32				return -1;
33	
34			chunk = length;
35			if (chunk > FLASH_PROG_BYTES)
36				chunk = FLASH_PROG_BYTES;
37			if (chunk == FLASH_PROG_BYTES) {
38				if (ops->program(offset, source, FLASH_PROG_BYTES) != 0)
39					return -1;
40			} else {
41				for (index = 0; index < FLASH_PROG_BYTES; index++)
42					scratch[index] = 0xff;
43				for (index = 0; index < chunk; index++)
44					scratch[index] = source[index];
45				if (ops->program(offset, scratch, FLASH_PROG_BYTES) != 0)
46					return -1;
47			}
48			offset += FLASH_PROG_BYTES;
49			source += chunk;
50			length -= chunk;
51		}
52		return 0;
53	}
54	
55	/*
56	 * Rewrite an arbitrary program-page-aligned range through a spare sector.
57	 * The copy makes every untouched page available after the destination erase,
58	 * so temporary swap devices retain ordinary block-rewrite semantics without
59	 * a full erase sector in SRAM.
60	 */
61	int
62	flash_swap_rewrite(const struct flash_swap_ops *ops, unsigned int offset,
63	    const unsigned char *source, unsigned int length,
64	    unsigned int spare_sector, unsigned char *scratch)
65	{
66		unsigned int chunk, destination_sector, page, page_offset;
67	
68		if ((offset & (FLASH_PROG_BYTES - 1)) != 0 ||
69		    (length & (FLASH_PROG_BYTES - 1)) != 0 ||
70		    (spare_sector & (FLASH_SECTOR_BYTES - 1)) != 0 ||
71		    offset + length < offset)
72			return -1;
73	
74		while (length != 0) {
75			destination_sector = offset & ~(FLASH_SECTOR_BYTES - 1);
76			if (destination_sector == spare_sector)
77				return -1;
78			chunk = FLASH_SECTOR_BYTES - (offset - destination_sector);
79			if (chunk > length)
80				chunk = length;
81	
82			if (ops->erase(spare_sector, FLASH_SECTOR_BYTES) != 0)
83				return -1;
84			for (page = 0; page < FLASH_SECTOR_BYTES;
85			    page += FLASH_PROG_BYTES) {
86				if (ops->read(destination_sector + page, scratch,
87				    FLASH_PROG_BYTES) != 0 ||
88				    ops->program(spare_sector + page, scratch,
89				    FLASH_PROG_BYTES) != 0)
90					return -1;
91			}
92			if (ops->erase(destination_sector, FLASH_SECTOR_BYTES) != 0)
93				return -1;
94	
95			for (page = 0; page < FLASH_SECTOR_BYTES;
96			    page += FLASH_PROG_BYTES) {
97				page_offset = destination_sector + page;
98				if (page_offset >= offset &&
99				    page_offset < offset + chunk) {
100					if (ops->program(page_offset,
101					    source + page_offset - offset,
102					    FLASH_PROG_BYTES) != 0)
103						return -1;
104				} else {
105					if (ops->read(spare_sector + page, scratch,
106					    FLASH_PROG_BYTES) != 0 ||
107					    ops->program(page_offset, scratch,
108					    FLASH_PROG_BYTES) != 0)
109						return -1;
110				}
111			}
112			offset += chunk;
113			source += chunk;
114			length -= chunk;
115		}
116		return 0;
117	}
